style.css:
@-moz-document domain("google.com") {
/* Fond GIF complet */
    body {
        background: url("https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExNmhteXIyNHo0NXRqdHhscWNybzMxcWFmMmhmNmZhNzdzaDNrZWpreiZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/1PJ4R2yJcl5vLnn87m/giphy.gif") 
                    no-repeat center center fixed !important;
        background-size: cover !important; /* Remplit tout l'écran */
        background-color: black !important;
        color: white !important; /* Texte par défaut en blanc */
    }

    /* Texte partout en blanc */
    h1, h2, h3, h4, h5, h6, p, span, li, td, th, a {
        color: white !important;
    }

    /* Liens avec contraste */
    a {
        color: #00bfff !important;
    }
    a:visited {
        color: #ff69b4 !important;
    }

    /* Sélection de texte */
    ::selection {
        background: #3390ff !important; /* bleu classique Chrome */
        color: white !important;
    }

    /* Supprimer tout fond blanc pour laisser le GIF visible */
    * {
        background: transparent !important;
    }
}
